
local YvnpyrAUrqk="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function mBZMUtW(data)
    data=data:gsub("[^"..YvnpyrAUrqk.."=]","")
    return (data:gsub(".",function(x)
        if x=="=" then return "" end
        local r,f="",(YvnpyrAUrqk:find(x)-1)
        for i=6,1,-1 do
            r=r..(f%2^i-f%2^(i-1)>0 and "1" or "0")
        end
        return r
    end):gsub("%d%d%d%d%d%d%d%d",function(x)
        return string.char(tonumber(x,2))
    end))
end

local yPSLHW=""

if #yPSLHW < 100 then return error("tamper") end

local pZIsCuJ = mBZMUtW(mBZMUtW(yPSLHW))

local function eupjcC(s)
    local h=0
    for i=1,#s do
        h = (h + string.byte(s,i)*i) % 9999999
    end
    return tostring(h)
end

if eupjcC(pZIsCuJ) == "0" then
    return error("tampered")
end

for i=1,math.random(3,7) do
    local _ = tostring(math.random()):reverse()
end

loadstring(pZIsCuJ)()
